import random

def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def neighbors(r, c):
        return [(r + dr, c + dc) for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)] if is_valid(r + dr, c + dc)]

    def dfs(r, c, path):
        if (r, c) == goal:
            return path + [(r, c)]
        for _ in range(4):
            dr, dc = [(-1, 0), (1, 0), (0, -1), (0, 1)][random.randint(0, 3)]
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in path:
                result = dfs(nr, nc, path + [(nr, nc)])
                if result:
                    return result
        return []

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    return dfs(start[0], start[1], [start])
