import random
import sys
sys.setrecursionlimit(10000)

def solve(grid, start, goal):
    if start == goal:
        return [start]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    visited = set()
    path = []

    def dfs(current):
        nonlocal path
        path.append(current)
        if current == goal:
            return True
        visited.add(current)
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy
            if (nx, ny) not in visited and 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.':
                if dfs((nx, ny)):
                    return True
        path.pop()
        return False

    dfs(start)
    return path if path[-1] == goal else []

