def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if start == goal:
        return [start]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    visited = [[False for _ in range(cols)] for _ in range(rows)]
    path = [[-1 for _ in range(cols)] for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '.' and not visited[i][j]:
                visited[i][j] = True
                path[i][j] = -1
                queue = [(i, j)]
                while queue:
                    x, y = queue.pop(0)
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and not visited[nx][ny]:
                            visited[nx][ny] = True
                            path[nx][ny] = (x, y)
                            queue.append((nx, ny))
                            if (nx, ny) == goal:
                                break
                    if (x, y) == goal:
                        break
                if (x, y) == goal:
                    break

    if path[goal[0]][goal[1]] == -1:
        return []

    result = []
    x, y = goal
    while (x, y) != start:
        result.append((x, y))
        x, y = path[x][y]
    result.append(start)
    result.reverse()
    return result
